// Sortie structurée du cœur RAG, utilisée par le chat (WF2) et les évaluations (WF3).
const c = $('Construire le contexte').first().json;
const brute = String($input.first().json.text || '').trim();

// Correction déterministe des titres de rubrique déformés par le modèle
// (ex. « ### À dire al client » → « ### À dire au client »), par distance d'édition.
const TITRES = ['Réponse courte', 'Étapes à suivre', 'À dire au client', 'Vigilance', 'Escalade', 'Source'];
const cle = s => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z]/g, '');
const distance = (a, b) => {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length];
};
let titres_corriges = 0;
const reponse = brute.split('\n').map(ligne => {
  const m = ligne.match(/^#{1,4}\s*(.+?)\s*:?\s*$/);
  if (!m) return ligne;
  const meilleur = TITRES.map(t => ({ t, d: distance(cle(m[1]), cle(t)) })).sort((x, y) => x.d - y.d)[0];
  const attendu = '### ' + meilleur.t;
  if (meilleur.d <= 3 && ligne !== attendu) { titres_corriges++; return attendu; }
  return ligne;
}).join('\n');

return [{ json: {
  reponse,
  reponse_brute: brute,
  titres_corriges,
  refus: reponse.includes('Information non trouvée dans la documentation'),
  docs_recuperes: c.docs_recuperes,
  passages: c.passages,
  contexte: c.contexte,
  top_k: c.top_k,
  modele: c.modele,
  prompt_version: c.prompt_version,
  duree_ms: Date.now() - c.t0,
} }];
